module t.alpha @ 0.1

use std.{fs, net, model, exec, git}

capability ModelStd  = model.infer(tier: standard, max_class: internal)
capability ModelEco  = model.infer(tier: economy)
capability ModelBig  = model.infer(tier: big, max_class: confidential)
capability Web       = net.https(hosts: ["b.example", "a.example"])
capability WebAny    = net.https(hosts: ["a.example", "c.example"])
capability Repo      = fs.read("/work/repo")
capability Src       = fs.write("/work/repo/src")
capability SrcGen    = fs.write("/work/repo/src/gen", "/work/repo/lib/")
capability Run       = exec(commands: ["make", "sh"], args_prefix: [["-c", "a"], ["-c", "b"]])
capability RunAny    = exec(commands: ["sh"])
capability RunAgain  = exec(commands: ["make"], args_prefix: [["-c", "a"]])

type Note = { text: Text }

agent Planner {
  role   "Plans."
  caps   ModelStd, ModelEco, Web, Repo
  budget { tokens: 5000, spend: 0.02 USD, steps: 4 }
  skill plan(task: Text) -> Inferred<Note> ! {Model, Net, Fs.Read}
}

agent Worker {
  role   "Builds."
  caps   ModelBig, WebAny, Src, SrcGen, Run, RunAny, RunAgain
  budget { tokens: 1M, spend: 5 USD, steps: 5, time: 5m }
  skill build(task: Text) -> Inferred<Note> ! {Model, Fs.Write, Exec, Net}
  skill quick(task: Text) -> Inferred<Note> ! {Model} budget { tokens: 100, spend: 0.0001 USD, steps: 3, time: 1m }
}

agent Idle {
  role   "Has no model."
  caps   Repo
  budget { tokens: 10, steps: 2 }
  skill look(task: Text) -> Inferred<Note> ! {Fs.Read}
}

agent remote Far = a2a("https://far.example/.well-known/agent-card.json")
  version "1.0"
  trust   untrusted
  caps    net.https(hosts: ["far.example"])
  skills {
    ask(task: Text) -> Note
  }

agent Scripted {
  role   "Has a skill with a body."
  caps   ModelStd
  budget { tokens: 5, steps: 100 }
  skill fmt(task: Text) -> Text ! {Model} budget { tokens: 1, steps: 100 } { task }
  skill think(task: Text) -> Inferred<Note> ! {Model}
}

